const D = { density: .55, energy: .6, hue: 135, speed: 1, scale: 1, x: .5, y: .5, seed: 0, style: 'pcb', act: 'flow' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const um = Math.min(width,height);
const H = P.hue;
const mg = um * 0.05;
const traceH = sty==='amber' ? 38 : (sty==='xray' ? 190 : (sty==='thermal' ? 40 : (H+22)%360));

S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.tre  = (S.tre ||0)*.82 + (A.treble||0)*.18;
const glow = (.4 + .6*P.energy) * (.5 + .6*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// ---- (re)build deterministic trace network ----
const GX = Math.round(9 + P.density*11);
const GY = Math.round(7 + P.density*9);
const NT = Math.round(12 + P.density*44);
const bkey = P.seed+'|'+GX+'|'+GY+'|'+NT+'|'+cl(P.scale,.4,2.4).toFixed(2);
if (S.bkey !== bkey) {
  S.bkey = bkey;
  const T = [];
  for (let ti=0; ti<NT; ti++){
    let gx = Math.floor(fr(ti*13)*GX), gy = Math.floor(fr(ti*13+1)*GY);
    const len = 3 + Math.floor(fr(ti*13+2)*6);
    const pts = [[gx,gy]];
    let dir = Math.floor(fr(ti*13+3)*4);
    for (let k=0;k<len;k++){
      if (fr(ti*13+4+k) < .38) dir = (dir + (fr(ti*17+k)<.5?1:3)) % 4;
      const d = [[1,0],[0,1],[-1,0],[0,-1]][dir];
      gx = Math.max(0,Math.min(GX,gx+d[0])); gy = Math.max(0,Math.min(GY,gy+d[1]));
      pts.push([gx,gy]);
    }
    T.push({ pts, off: fr(ti*13+11), spd: .5+fr(ti*13+12), diag: fr(ti*13+7)<.28 });
  }
  S.T = T;
  // components + LEDs at some nodes
  const C = [];
  for (let ci=0; ci<Math.round(6+P.density*16); ci++){
    C.push({ gx: fr(ci*23)*GX, gy: fr(ci*23+1)*GY, w: .6+fr(ci*23+2)*1.4, h: .5+fr(ci*23+3)*1.0, led: fr(ci*23+4)<.5, ph: fr(ci*23+5)*TAU });
  }
  S.C = C;
}
const px = gx => mg + (gx/GX)*(width-2*mg);
const py = gy => mg + (gy/GY)*(height-2*mg);
const cw = (width-2*mg)/GX, chh = (height-2*mg)/GY;
const tw = Math.max(1.4, um*0.006*cl(P.scale,.4,2.4));

// pixel polylines + cumulative length (rebuilt each frame — cheap, size-safe)
const PL = S.T.map(tr => {
  const p = tr.pts.map(g => [px(g[0]),py(g[1])]);
  let tot=0; const seg=[];
  for (let i=0;i<p.length-1;i++){ const l=Math.hypot(p[i+1][0]-p[i][0], p[i+1][1]-p[i][1]); seg.push(l); tot+=l; }
  return { p, seg, tot, tr };
});
const ptAt = (o,f) => {
  let d=f*o.tot;
  for (let i=0;i<o.seg.length;i++){ if (d<=o.seg[i] || i===o.seg.length-1){ const u=o.seg[i]>0?cl(d/o.seg[i],0,1):0; return [o.p[i][0]+(o.p[i+1][0]-o.p[i][0])*u, o.p[i][1]+(o.p[i+1][1]-o.p[i][1])*u]; } d-=o.seg[i]; }
  return o.p[0];
};

// ---- cached board (mask, traces, pads, silkscreen) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+bkey;
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  // solder mask
  for (let i=0;i<48;i++){ const f=i/48;
    let h,s,b;
    if (sty==='xray'){ h=H; s=30; b=4+3*f; }
    else if (sty==='amber'){ h=34; s=30; b=3+3*f; }
    else if (sty==='thermal'){ h=245; s=60; b=8+8*f; }
    else { h=(H)%360; s=55; b=14+10*f; }  // green mask
    g.fill(h,s,b,100); g.rect(0, f*height, width, height/48+1);
  }
  // etch grid dots
  g.noStroke();
  for (let a=0;a<=GX;a++) for (let bb=0;bb<=GY;bb++){
    g.fill(traceH, sty==='xray'?40:30, sty==='xray'?30:40, 6); g.ellipse(px(a),py(bb),1.6,1.6);
  }
  // traces (gold copper) with under-shadow
  for (const tr of S.T){ const p = tr.pts.map(gp=>[px(gp[0]),py(gp[1])]);
    g.noFill();
    g.stroke(sty==='thermal'?250:traceH, sty==='xray'?60:70, sty==='xray'?20:18, 60); g.strokeWeight(tw+2.4);
    g.beginShape(); for (const q of p) g.vertex(q[0],q[1]); g.endShape();
    g.stroke(sty==='thermal'?45:traceH, sty==='amber'?70:(sty==='xray'?55:60), sty==='xray'?55:70, 92); g.strokeWeight(tw);
    g.beginShape(); for (const q of p) g.vertex(q[0],q[1]); g.endShape();
    // pads at ends
    for (const e of [p[0],p[p.length-1]]){
      if (sty==='xray'){ g.noFill(); g.stroke(traceH,60,100,70); g.strokeWeight(1.4); g.ellipse(e[0],e[1],tw*3.4,tw*3.4); g.noStroke(); }
      else { g.noStroke(); g.fill(traceH,40,sty==='amber'?70:78,100); g.ellipse(e[0],e[1],tw*3.2,tw*3.2);
             g.fill(0,0,sty==='amber'?4:8,100); g.ellipse(e[0],e[1],tw*1.4,tw*1.4); }
    }
  }
  // component silkscreen
  for (const c of S.C){ const X=px(c.gx),Y=py(c.gy), w=c.w*cw*.7, h=c.h*chh*.7;
    if (sty==='xray'){ g.noFill(); g.stroke(H,20,80,50); g.strokeWeight(1); g.rect(X-w/2,Y-h/2,w,h); g.noStroke(); }
    else { g.noStroke(); g.fill(0,0,sty==='amber'?10:6,100); g.rect(X-w/2,Y-h/2,w,h,2);
           g.noFill(); g.stroke(0,0,90,sty==='amber'?20:34); g.strokeWeight(1); g.rect(X-w/2,Y-h/2,w,h,2); g.noStroke(); }
  }
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- traveling signal pulses (real-time, never re-phases) ----
push(); blendMode(ADD); noStroke();
const rate = P.speed*(.20 + .16*K.intensity) * (P.act==='pulse' ? (1+1.2*kick) : 1);
let boot = 1;
if (P.act === 'boot') boot = 0;
for (let i=0;i<PL.length;i++){ const o=PL[i], tr=o.tr;
  if (P.act === 'boot'){ boot = cl(1.2 - Math.abs(((K.t*.12)%PL.length) - i)*0.7, 0, 1); if (boot<=0.02) continue; }
  const f = (tr.off + K.t*rate*tr.spd) % 1;
  const nseg = 5;
  for (let s=0;s<nseg;s++){ const ff=(f - s*0.05 + 1)%1; const pt=ptAt(o,ff);
    const a=(sty==='thermal'? (16-s*2.4) : (18-s*2.6))*glow*boot;
    const hh = sty==='thermal' ? cl(60 - s*10, 0, 60) : (sty==='xray'? traceH : (sty==='amber'?46:(H+50)%360));
    fill(hh, sty==='thermal'?(60+ s*6):40, 100, cl(a,0,26)); ellipse(pt[0],pt[1], tw*(2.6-s*0.32), tw*(2.6-s*0.32));
  }
  // head glint (bright core, no shadowBlur — kept cheap across many traces)
  const hp = ptAt(o,f);
  const hh2 = sty==='amber'?46:(sty==='thermal'?55:(H+50)%360);
  fill(hh2, 30, 100, 22*glow*boot); ellipse(hp[0],hp[1], tw*3.2, tw*3.2);
  fill(0,0,100, 26*glow*boot); ellipse(hp[0],hp[1], tw*1.4, tw*1.4);
}
pop();

// ---- traveling inspection sweep: bright band crossing the whole board (REAL-TIME motion floor) ----
// fixed-SECONDS period so it never re-phases at the 8s motion-gate sample (resolution-independent)
push(); blendMode(ADD); noStroke();
const swSpan = width + um*0.4;
const swPeriod = 6.4 / Math.max(0.3, 0.5 + P.speed*0.6);   // seconds per full crossing
const swPhase = (K.t % swPeriod) / swPeriod;
const swx = swPhase*swSpan - um*0.2;
const swBW = um*0.13;
const swH = sty==='amber'?46 : (sty==='thermal'?55 : (sty==='xray'?traceH : (H+50)%360));
for (let s=-2;s<=2;s++){
  const sa = (7 - Math.abs(s)*2.0)*glow;
  fill(swH, sty==='xray'?60:40, 100, cl(sa,0,13));
  rect(swx + s*swBW*0.34 - swBW/2, 0, swBW, height);
}
pop();

// ---- blinking LEDs / component glints ----
push(); blendMode(ADD); noStroke();
for (const c of S.C){ if (!c.led) continue; const X=px(c.gx),Y=py(c.gy);
  const tw2 = .5 + .5*Math.sin(K.t*1.3 + c.ph);
  const on = cl(tw2*.5 + kick*.6 + S.tre*.5, 0, 1);
  if (on < .05) continue;
  const hh = sty==='thermal' ? 55 : (sty==='amber'?46 : (c.ph>3 ? (H+180)%360 : (H+40)%360));
  drawingContext.shadowBlur = 10*on*glow; drawingContext.shadowColor = color(hh,80,100,90).toString();
  fill(hh, 60, 100, 30*on*glow); ellipse(X,Y, tw*2.6, tw*2.6);
  fill(0,0,100, 24*on); ellipse(X,Y, tw*1.1, tw*1.1);
  drawingContext.shadowBlur = 0;
}
pop();

// ---- thermal hot-bloom around anchor (partial, real-time) ----
if (sty==='thermal'){ push(); blendMode(ADD); noStroke();
  const hx=cl(P.x,0,1)*width, hy=cl(P.y,0,1)*height, r=um*(.3+.1*Math.sin(K.t*.3));
  for (let i=0;i<5;i++){ fill(cl(60-i*12,0,60), 70, 100, 4*glow); ellipse(hx,hy, r*(1.2-i*.18), r*(1.2-i*.18)); }
  pop(); }

// ---- bus-sync sweep flash on beat (partial-frame, safe) ----
push(); blendMode(ADD); noStroke();
const flare = (kick*.5 + K.swell*.3)*glow;
fill(sty==='amber'?46:(sty==='thermal'?55:traceH), sty==='xray'?70:45, 100, 5*flare);
rect(0, cl(P.y,0,1)*height - um*.12, width, um*.24);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
